def transform(grid):
    H, W = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find all cells with 9
    nines = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 9:
                nines.add((r, c))

    # Check each 4
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 4:
                # Check if between two 9s in same row
                found_before = False
                found_after = False
                for nc in range(W):
                    if nc < c and (r, nc) in nines:
                        found_before = True
                    if nc > c and (r, nc) in nines:
                        found_after = True
                if found_before and found_after:
                    result[r][c] = 2
                    continue

                # Check if between two 9s in same column
                found_before = False
                found_after = False
                for nr in range(H):
                    if nr < r and (nr, c) in nines:
                        found_before = True
                    if nr > r and (nr, c) in nines:
                        found_after = True
                if found_before and found_after:
                    result[r][c] = 2

    return result

output = transform(grid)
print(output)

